mapper.select:
SELECT , i.path AS thumbnail FROM FEED f
LEFT JOIN IMAGES i ON f.code = i.target_code AND i.type = 'feed' AND i.order_seq = 1
LEFT JOIN FEED_HASHTAG fh ON f.code = fh.feed_code WHERE f.status = 'active' AND f.delete_yn = 0 ORDER BY f.created_at DESC, f.code DESC LIMIT #{offset}, #{perPage}
